export async function fetchKulturhusetEvents(options = {}) {
  const { limit = 20, page = 0 } = options;

  // Use explicit date instead of 'now' for broader compatibility
  const today = new Date().toISOString().split('T')[0];

  const query = {
    size: limit,
    from: page * limit,
    query: {
      bool: {
        must: [
          {
            range: {
              tixStartDate: {
                gte: today,  // Only future events
              },
            },
          },
        ],
      },
    },

